WITH wp_counts AS ( SELECT wp_customer_sk, COUNT(*) AS wp_cnt FROM web_page GROUP BY wp_customer_sk ), sales_by_customer AS ( SELECT cs.cs_bill_customer_sk AS cust_sk, cs.cs_order_number, cs.cs_net_profit, cs.cs_net_paid, cs.cs_sold_time_sk, COALESCE(wp_counts.wp_cnt, 0) AS wp_cnt FROM catalog_sales cs LEFT JOIN wp_counts ON cs.cs_bill_customer_sk = wp_counts.wp_customer_sk ), customer_summary AS ( SELECT c.c_customer_id, c.c_customer_sk, MIN(sbc.cs_order_number) AS first_order_number, MAX(sbc.cs_order_number) AS last_order_number, COUNT(sbc.cs_order_number) AS total_orders, SUM(sbc.cs_net_profit) AS total_net_profit, SUM(sbc.cs_net_paid) AS total_net_paid, MAX(sbc.cs_sold_time_sk) AS latest_sold_time_sk, COALESCE(MAX(sbc.wp_cnt), 0) AS web_page_count FROM customer c LEFT JOIN sales_by_customer sbc ON c.c_customer_sk = sbc.cust_sk GROUP BY c.c_customer_id, c.c_customer_sk ), customer_status AS ( SELECT cs.c_customer_id, cs.c_customer_sk, cs.first_order_number, cs.last_order_number, cs.total_orders, cs.total_net_profit, cs.total_net_paid, cs.web_page_count, cs.latest_sold_time_sk, CASE WHEN cs.total_orders = 0 THEN 'NO_PURCHASE' WHEN cs.last_order_number - cs.first_order_number < 1000 THEN 'NEW' WHEN cs.last_order_number - cs.first_order_number BETWEEN 1000 AND 5000 THEN 'ACTIVE' ELSE 'CHURNED' END AS churn_flag, DENSE_RANK() OVER (ORDER BY cs.total_net_profit DESC) AS ltv_rank FROM customer_summary cs ) SELECT cs.c_customer_id, cs.first_order_number, cs.last_order_number, cs.total_orders, cs.total_net_profit, cs.total_net_paid, cs.web_page_count, t.t_hour AS latest_sale_hour, t.t_shift AS latest_sale_shift, cs.churn_flag, cs.ltv_rank FROM customer_status cs LEFT JOIN time_dim t ON cs.latest_sold_time_sk = t.t_time_sk WHERE cs.total_orders >= 5 ORDER BY cs.ltv_rank LIMIT 20
